class Solution {
public:
    void reverseWords(vector<char>& s) {
        auto rev = [&](int l, int r) {
            while (l < r) {
                swap(s[l++], s[r--]);
            }
        };
        int n = s.size();
        rev(0, n - 1);
        int start = 0;
        for (int i = 0; i <= n; ++i) {
            if (i == n || s[i] == ' ') {
                rev(start, i - 1);
                start = i + 1;
            }
        }
    }
};

class Solution {
    public void reverseWords(char[] s) {
        int n = s.length;
        reverse(s, 0, n - 1);
        int start = 0;
        for (int i = 0; i <= n; i++) {
            if (i == n || s[i] == ' ') {
                reverse(s, start, i - 1);
                start = i + 1;
            }
        }
    }

    private void reverse(char[] s, int l, int r) {
        while (l < r) {
            char tmp = s[l];
            s[l++] = s[r];
            s[r--] = tmp;
        }
    }
}

/**
 * @param {character[]} s
 * @return {void} Do not return anything, modify s in-place instead.
 */
var reverseWords = function(s) {
    function rev(l, r) {
        while (l < r) {
            const tmp = s[l];
            s[l++] = s[r];
            s[r--] = tmp;
        }
    }
    const n = s.length;
    rev(0, n - 1);
    let start = 0;
    for (let i = 0; i <= n; i++) {
        if (i === n || s[i] === ' ') {
            rev(start, i - 1);
            start = i + 1;
        }
    }
};
